// Helper to get visuals by category
export const getVisualsByCategory = (category: string): VisualAsset[] =>
  allVisuals.filter(v => v.category === category);

// Helper to get a slice of visuals for a page
export const getVisualsForPage = (categories: string[], count: number = 32): VisualAsset[] => {
  const filtered = allVisuals.filter(v => categories.includes(v.category));
  return filtered.slice(0, count);
};

// Total visual count — 555 original + 630 expansion + 13,000 mega = 14,185+ visuals
export const TOTAL_VISUAL_COUNT = allVisuals.length;

